1	import { describe, it, expect } from "vitest";
2	import { runScenario } from "./claim-office.js";
3	
4	describe("MHPCO Claim Office — quote: base premiums", () => {
5	  it("empty item list → premium 5 G (only the processing fee)", () => {
6	    const results = runScenario({
7	      customer: { yearsWithMHPCO: 0 },
8	      steps: [{ op: "quote", items: [] }],
9	    });
10	
11	    expect(results).toEqual([{ premium: 5 }]);
12	  });
13	  it.todo("a sword → base premium 100 G");
14	  it.todo("an amulet → base premium 60 G");
15	  it.todo("a staff → base premium 80 G");
16	  it.todo("a potion → base premium 40 G");
17	  it.todo("a single rune (component) → base premium 25 G");
18	  it.todo("a single moonstone (component) → base premium 25 G");
19	});
20	
21	describe("MHPCO Claim Office — quote: component blocks of 3 alike", () => {
22	  it.todo("2 runes → 50 G base premium (no block)");
23	  it.todo("3 runes → 60 G base premium (block applies)");
24	  it.todo("4 runes → 100 G base premium (no block — block requires exactly 3)");
25	  it.todo("7 runes → 175 G base premium");
26	  it.todo("2 runes + 1 moonstone → 75 G base premium (no block: different types)");
27	  it.todo("3 runes + 3 moonstones → 120 G base premium (two separate blocks)");
28	});
29	
30	describe("MHPCO Claim Office — quote: premium modifiers", () => {
31	  it.todo("a cursed sword adds a 50 % risk surcharge on the item's base premium");
32	  it.todo("a sword with enchantment 5 adds a 30 % high-enchantment surcharge");
33	  it.todo("a sword with enchantment 4 → no high-enchantment surcharge");
34	  it.todo("a cursed sword with enchantment 5 → both surcharges apply");
35	  it.todo("a customer with exactly 2 years with MHPCO → 20 % loyalty discount applies");
36	  it.todo("a customer with 1 year with MHPCO → no loyalty discount");
37	  it.todo("every quote carries a 10 % first insurance surcharge on the policy base premium");
38	  it.todo("the second quote in a scenario receives a 15 % follow-up contract discount");
39	  it.todo("a 5 G processing fee is added at the very end of every premium");
40	});
41	
42	describe("MHPCO Claim Office — quote: modifier scope on multi-item policies", () => {
43	  it.todo("cursed sword + plain amulet → item surcharge is 50 G (50 % of the cursed item only), 210 G before policy modifiers and fee");
44	  it.todo("policy-wide modifiers apply to the sum of all item base premiums");
45	});
46	
47	describe("MHPCO Claim Office — quote: rounding in the MHPCO's favor", () => {
48	  it.todo("a premium calculation yielding 197.5 G → final premium 198 G (rounded up)");
49	  it.todo("intermediate amounts are kept as fractions; only the final premium is rounded");
50	});
51	
52	describe("MHPCO Claim Office — quote: integration examples", () => {
53	  it.todo("newcomer (0 years) with a cursed steel sword, enchantment 3 → premium 165 G");
54	  it.todo("long-standing customer (3 years), second quote, cursed steel sword enchantment 7 → premium 160 G");
55	});
56	
57	describe("MHPCO Claim Office — claim: standard reimbursement", () => {
58	  it.todo("regular sword (steel, enchantment 3), damage 500 G → payout 400 G");
59	  it.todo("damage to a rune (no enchantment or material), damage 200 G → payout 100 G");
60	  it.todo("a claim reports the remaining cap after the payout");
61	});
62	
63	describe("MHPCO Claim Office — claim: special clauses", () => {
64	  it.todo("dragon-material sword, enchantment 5, damage 800 G → payout 700 G (full reimbursement, then deductible)");
65	  it.todo("steel sword, enchantment 9, damage 1000 G → payout 400 G (50 % first, then deductible)");
66	  it.todo("dragon-material sword, enchantment 9, damage 1000 G → payout 400 G (the 50 % rule wins)");
67	  it.todo("dragon-material sword with exactly enchantment 8, damage 1000 G → payout 400 G");
68	});
69	
70	describe("MHPCO Claim Office — claim: deductible per damage event", () => {
71	  it.todo("dragon attack damaging an insured sword (500 G) and an insured amulet (300 G) → payout 600 G (deductible once per damaged item)");
72	});
73	
74	describe("MHPCO Claim Office — claim: rounding in the MHPCO's favor", () => {
75	  it.todo("a payout calculation yielding 350.5 G → final payout 350 G (rounded down)");
76	});
77	
78	describe("MHPCO Claim Office — claim: insurance sum and cap", () => {
79	  it.todo("a policy covering a sword and an amulet → insurance sum 1600 G, cap 3200 G");
80	  it.todo("a cursed sword (premium with modifiers 165 G) → cap 2000 G (premium modifiers do not raise the cap)");
81	  it.todo("a policy covering a sword and 3 runes (a block) → insurance sum 1750 G, cap 3500 G");
82	  it.todo("sword insured (cap 2000 G), first claim of 1500 G → payout 1400 G, remaining cap 600 G");
83	  it.todo("sword insured (cap 2000 G), second claim of 1500 G → payout 600 G, remaining cap 0 G");
84	});
85	
86	describe("MHPCO Claim Office — multiple items of the same type", () => {
87	  it.todo("a policy covering two swords → insurance sum 2000 G, cap 4000 G");
88	  it.todo("a dragon attack damaging both swords → each damage entry gets its own deductible");
89	  it.todo("more damage entries of a type than the policy covers → error (whole claim rejected)");
90	});
91	
92	describe("MHPCO Claim Office — error cases", () => {
93	  it.todo("quote includes an item with an unknown type (e.g. broomstick) → error");
94	  it.todo("claim references a damage entry whose item is not part of the policy → error");
95	  it.todo("claim references a damage entry with an unknown item type → error");
96	  it.todo("claim contains a damage entry with amount -200 → error");
97	});
98	
99	describe("MHPCO Claim Office — CLI", () => {
100	  it.todo("reads a JSON scenario from stdin and writes {results: [...]} to stdout");
101	  it.todo("results array has the same length and order as the input steps");
102	  it.todo("on an invalid scenario → exits with a non-zero status code, writes an error description to stderr and no results to stdout");
103	});
